            "body": "Угол между прямой и плоскостью — это угол с её проекцией: sin φ = (расстояние от точки прямой до плоскости)/(длина отрезка). Удобно опускать перпендикуляр из точки, расстояние от которой уже известно (из точки прямой, параллельной плоскости). Угол между плоскостями: (1) линейный угол — перпендикуляры к линии пересечения в каждой плоскости; (2) через площадь проекции: S_пр = S·cos φ; (3) как угол между нормалями или между прямыми, перпендикулярными плоскостям (α ⊥ BD₁, (ABC) ⊥ BB₁ ⇒ угол = ∠(BD₁, BB₁)); (4) по формуле cos φ = |n₁·n₂|/(|n₁|·|n₂|). Расстояние от точки до плоскости: строим перпендикуляр внутри вспомогательной плоскости, перпендикулярной данной (например, высота прямоугольного треугольника h = ab/c). Если SA ⊥ основанию и ABCD — прямоугольник, то d(A, (SBC)) = SA·AB/SB. Другие способы — метод объёмов (V = (1/3)·S·h, считаем двумя способами) и формула d = |ax₀ + by₀ + cz₀ + d|/√(a² + b² + c²). Расстояние между скрещивающимися прямыми: (1) общий перпендикуляр; (2) расстояние от одной прямой до параллельной ей плоскости, содержащей другую; (3) если одна прямая ⊥ плоскости, содержащей другую, то ищем расстояние от точки пересечения до второй прямой в этой плоскости; (4) объём тетраэдра V = (1/6)·a·b·d·sin φ, где a, b — противоположные рёбра, d — расстояние, φ — угол между ними. Построение сечения методом следов: продолжаем прямую сечения в грани до пересечения с прямой основания, полученную точку соединяем с точкой сечения в соседней грани. При параллельном переносе: если секущая плоскость содержит прямую, параллельную грани, то в этой грани след параллелен ей. Отношения отрезков на рёбрах: теорема о пропорциональных отрезках (Фалес) для параллельных прямых и теорема Менелая в плоском треугольнике (выбираем треугольник, на сторонах которого лежат нужные точки). Часто нужна цепочка из 2–3 применений Менелая. Правильная пирамида. Вершина проецируется в центр основания. Апофема ⊥ ребру основания. В правильной треугольной пирамиде центр делит медиану основания в отношении 2 : 1. В правильном тетраэдре отрезок между серединами противоположных рёбер ⊥ обоим рёбрам, а сами противоположные рёбра перпендикулярны. Если в правильной четырёхугольной пирамиде сторона : ребро = 1 : √2, то треугольник SBD равносторонний. Справочные формулы. Правильный треугольник: h = a√3/2, r = a√3/6, R = a√3/3, S = a²√3/4. Квадрат: диагональ a√2. Правильный шестиугольник: S = 3√3·a²/2, большая диагональ 2a. Медиана: mₐ = ½·√(2b² + 2c² − a²). Сечение с перпендикулярными диагоналями: S = ½·d₁·d₂. Так считают, когда одна диагональ параллельна прямой, перпендикулярной плоскости, содержащей другую (PF ∥ AC ⊥ (SBD) ∋ BX). Перпендикулярность прямой и плоскости через углы. Если в прямоугольном сечении tg одного острого угла равен ctg другого, то их сумма 90°, и отрезки перпендикулярны (A₁C ⊥ FE). Вторую пересекающуюся прямую берём по теореме о трёх перпендикулярах. Равенство треугольников даёт равнобедренность сечения: равные прямоугольные треугольники по двум катетам (B₁C₁M = ACM, A₁B₁K = C₁B₁K). Тела вращения. Сечение конуса через вершину — равнобедренный треугольник из двух образующих. Угол между сечением и основанием строится через перпендикуляр из центра к хорде. Вписанный угол, опирающийся на диаметр, — прямой (∠ABC₁ = 90°, ∠ACB = 90°). Для перпендикулярных образующих хорда равна l√2. Отношения объёмов. У пирамид с общей высотой объёмы относятся как площади оснований. Для тетраэдров с общим трёхгранным углом: V′/V = (a′·b′·c′)/(a·b·c). Отсечённая от куба или призмы пирамида — это (1/6)·произведение трёх рёбер прямого угла. Объём большей части = весь объём − меньшая часть. Координатно-векторный метод — универсальная проверка. Вводим систему с началом в удобной вершине, находим нормаль плоскости как векторное произведение (или из уравнения ax + by + cz + d = 0) и считаем углы и расстояния по формулам. В правильной треугольной пирамиде удобно ставить начало в центр основания. Типичные ошибки: считать пирамиду правильной, когда это не сказано; путать угол между плоскостями с углом между их «произвольными» прямыми (линейный угол строится перпендикулярами к одной точке ребра); забывать доказать, что построенный отрезок действительно ⊥ плоскости (нужны две пересекающиеся прямые); при ответе через arccos брать модуль скалярного произведения (угол ≤ 90°)."
